#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

/* Vector x contains values between 0 and 100, inclusive.
   Count the number of values in [0,10), [10,20), … , [90,100]
   and store the counts in `bins`.  The implementation is safe for
   any number of OpenMP threads. */
void binsBy10Count(const std::vector<double>& x,
                   std::array<std::size_t, 10>& bins)
{
    // Initialise the output bins to zero.
    bins.fill(0);

    // Determine the maximum number of threads that may be used.
    const int max_threads = omp_get_max_threads();

    // One private histogram per thread to avoid race conditions.
    std::vector<std::array<std::size_t, 10>> local_bins(max_threads);
    for (int t = 0; t < max_threads; ++t) {
        local_bins[t].fill(0);
    }

    // Parallel loop: each thread updates its own private histogram.
    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < x.size(); ++i) {
            // Compute the bin index for the current value.
            int idx = static_cast<int>(x[i] / 10.0);   // floor division
            if (idx < 0) idx = 0;
            if (idx >= 10) idx = 9;   // values equal to 100 go to the last bin

            ++local_bins[tid][idx];
        }
    }

    // Reduce the per‑thread histograms into the final result.
    for (int t = 0; t < max_threads; ++t) {
        for (int b = 0; b < 10; ++b) {
            bins[b] += local_bins[t][b];
        }
    }
}
