    bins.fill(0);

    // Determine the maximum number of threads that may be used.
    const int max_threads = omp_get_max_threads();

    // One private histogram per thread to avoid race conditions.
    std::vector<std::array<std::size_t, 10>> local_bins(max_threads);
    for (int t = 0; t < max_threads; ++t) {
        local_bins[t].fill(0);
    }

    // Parallel loop: each thread updates its own private histogram.
    #pragma omp parallel
